ValidationRule.errorConditionFormula:
AND( 
NOT( $Setup.PMC_ProcessSwitches__c.PMC_BypassValidationRule__c ) ,
OR(
OR( 
ISPICKVAL(  ProgramRebateType.RebateProgram.PMC_SS_SalesAgreement__r.PMC_SS_ApprovalStatus__c  , 'Approved'), 
ISPICKVAL( ProgramRebateType.RebateProgram.PMC_SS_SalesAgreement__r.PMC_SS_ApprovalStatus__c , 'Under Revision')  
),
ISPICKVAL( ProgramRebateType.RebateProgram.Status  , 'Inactive')
)

)
